#include "ActualAuthoringRecording.h"
#include "ResearchSettings.h"
using namespace Research;
static QImage scene(QWidget *base,QWidget *popup=nullptr){const auto ratio=base->devicePixelRatioF();QImage result(base->size()*ratio,QImage::Format_RGB32);result.setDevicePixelRatio(ratio);result.fill(Qt::white);QPainter p(&result);p.drawPixmap(QPoint(),base->grab());if(popup)p.drawPixmap(popup->mapToGlobal(QPoint())-base->mapToGlobal(QPoint()),popup->grab());p.end();return result;}
int main(int argc,char **argv){const auto report=argument(1);argc=1;TWApp app(argc,argv);app.setQuitOnLastWindowClosed(false);QTimer::singleShot(60,&app,[&]{
 const auto folder=QFileInfo(report).absolutePath(),bib=folder+"/paper/refs.bib";const QByteArray source="@article{hu2026,author={Hu, J.},title={A research note},year={2026},doi={10.1234/fixture}}\n@book{book,title={Collected papers},publisher={Press},year={2024}}\n";put(bib,source);QJsonArray checks;int failures=0;
 auto check=[&](const QString &name,bool pass){checks.append(QJsonObject{{"name",name},{"passed",pass}});failures+=!pass;put(report,QJsonDocument(QJsonObject{{"checks",checks},{"failures",failures},{"devicePixelRatio",qApp->primaryScreen()->devicePixelRatio()}}).toJson());};
 Tw::Settings().setValue("openPDFwithTeX",false);auto *w=new TeXDocumentWindow(bib);w->resize(1282,862);w->show();settle();w->findChild<QAction*>("researchInsertCitation")->trigger();auto *d=w->findChild<QDialog*>("researchCitationDialog");d->resize(1282,862);auto *list=d->findChild<QListWidget*>("researchCitationList");check("same peer bibliography loaded",waitFor([&]{return list->count()==2;}));for(int i=0;i<list->count();++i)if(list->item(i)->data(Qt::UserRole).toString()=="hu2026")list->setCurrentRow(i);settle(250);scene(d).save(folder+"/texline-bibliography.png");
 auto *timer=new QTimer(d);QObject::connect(timer,&QTimer::timeout,timer,[&]{auto *entry=d->findChild<QDialog*>("researchBibEntryDialog");if(!entry||!entry->isVisible())return;timer->stop();settle(250);check("same reference opens for field editing",entry->findChild<QLineEdit*>("researchBibField_title")->text()=="A research note");scene(d,entry).save(folder+"/texline-edit-reference.png");put(folder+"/comparison-geometry.json",QJsonDocument(QJsonObject{{"logicalWidth",d->width()},{"logicalHeight",d->height()},{"dpr",d->devicePixelRatioF()},{"capture","Actual Qt client and owned modal paints, no resampling"}}).toJson());key(entry,Qt::Key_Escape);});timer->start(20);d->findChild<QToolButton*>("researchCitationEditSource")->click();check("cancel preserves bibliography bytes and buffer",bytes(bib)==source&&w->textDoc()->editorText()==QString::fromUtf8(source));key(d,Qt::Key_Escape);settle();w->textDoc()->setModified(false);for(auto *window:TeXDocumentWindow::documentList())window->close();settle();app.exit(failures?1:0);
 });return app.exec();}
